const dateFmt = (s: string) => s ? new Date(s.slice(0, 10) + 'T00:00:00').toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' }) : '—';
const shortDate = (s: string) => s ? new Date(s.slice(0, 10) + 'T00:00:00').toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' }) : '—';
const statusNames: Row = { pending: 'Chờ duyệt', submitted: 'Đã gửi', approved: 'Đã duyệt', returned: 'Cần bổ sung', rejected: 'Không chấp nhận', open: 'Đang mở', locked: 'Đã chốt', completed: 'Hoàn thành', assigned: 'Chưa làm', redo: 'Cần làm lại', resolved: 'Đã giải quyết' };
const categoryNames: Row = { attendance: 'Chuyên cần', absence: 'Nghỉ học', learning: 'Học tập', speaking: 'Phát biểu', uniform: 'Đồng phục', discipline: 'Nề nếp', movement: 'Phong trào' };
